import React, { useState, useEffect } from "react";

export default function MissionLaunchCountdown({ onComplete }) {
  const [count, setCount] = useState(5);

  useEffect(() => {
    const timer = setInterval(() => {
      setCount((prev) => {
        if (prev === 1) {
          clearInterval(timer);
          setTimeout(onComplete, 1000); // Navigate after animation
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [onComplete]);

  return (
    <div className="fixed inset-0 bg-black bg-opacity-90 backdrop-blur-sm z-50 flex flex-col items-center justify-center text-white text-6xl font-bold transition-all duration-300">
      <div className="animate-ping text-cyan-400">{count > 0 ? count : "🚀 Launch!"}</div>
      {count === 0 && (
        <p className="text-lg text-cyan-300 mt-4 animate-fade-in">Engaging AI Protocols...</p>
      )}
    </div>
  );
}
